# 8-connected comps
seen=set(); comps8=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==2 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c));co=[]
   while q:
    a,b=q.pop();co.append((a,b))
    for x in range(max(0,a-1),min(R,a+2)):
     for y in range(max(0,b-1),min(C,b+2)):
      if grid[x][y]==2 and (x,y) not in seen:seen.add((x,y));q.append((x,y))
   comps8.append(co)
